/**
 * Codigos REJEITADOS empiricamente pelo sistema NFTS da PMSP (erro 310
 * 'Codigo do Servico Prestado invalido ou nao permitido') em importacao
 * real de 07/2026, embora constem do Anexo 1 ate IN 06/2024 e NAO estejam
 * na lista oficial de encerrados. Provavel efeito da reformulacao de
 * codigos de informatica de 01/01/2026. Bloqueados ate confirmacao do
 * codigo vigente na tela de emissao online.
 */
export const CODIGOS_REJEITADOS_PMSP: Set<string> = new Set(['02682', '02798', '02917']);

export const CATALOGO_POR_CODIGO: Map<string, CatalogoNftsRow[]> = new Map();
export const CATALOGO_POR_ITEM: Map<string, CatalogoNftsRow[]> = new Map();
for (const row of CATALOGO_NFTS_SP) {
    if (!CATALOGO_POR_CODIGO.has(row.codigo)) CATALOGO_POR_CODIGO.set(row.codigo, []);
    CATALOGO_POR_CODIGO.get(row.codigo)!.push(row);
    if (!CATALOGO_POR_ITEM.has(row.item)) CATALOGO_POR_ITEM.set(row.item, []);
    CATALOGO_POR_ITEM.get(row.item)!.push(row);
}
